Link: https://patch.msgid.link/fac6043fa20a2ff68e12958c431836f692c51268.1780113823.git.zzhan461@ucr.edu
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
The bug is a race condition in the SCTP sock_diag exact lookup path (`sctp_sock_dump_one`). The function can hold a transport reference, block on `lock_sock(sk)`, and then resume after another thread calls `sctp_association_free()`, which marks the association dead and frees its bind address list. Without a validity check after acquiring the lock, subsequent calls to `inet_assoc_attr_size()` and `inet_diag_msg_sctpasoc_fill()` dereference the freed or invalid association state (e.g., an empty bind-address list), leading to an out-of-bounds read or use-after-free.

Here is the patch:

 static int sctp_sock_dump_one(struct sctp_endpoint *ep, struct sctp_transport *tsp, void *p)
 {
 	struct sctp_association *assoc = tsp->asoc;
 	struct sctp_comm_param *commp = p;
 	struct sock *sk = ep->base.sk;
 	const struct inet_diag_req_v2 *req = commp->r;
 	struct sk_buff *skb = commp->skb;
 	struct sk_buff *rep;
 	int err;

 	err = sock_diag_check_cookie(sk, req->id.idiag_cookie);
 	if (err)
 		return err;

 	lock_sock(sk);

-	rep = nlmsg_new(inet_assoc_attr_size(sk, assoc), GFP_KERNEL);
-	if (!rep) {
-		release_sock(sk);
-		return -ENOMEM;
+	if (ep != assoc->ep || assoc->base.dead) {
+		err = -ESTALE;
+		goto out_unlock;
 	}

-	if (ep != assoc->ep) {
-		err = -EAGAIN;
-		goto out;
+	rep = nlmsg_new(inet_assoc_attr_size(sk, assoc), GFP_KERNEL);
+	if (!rep) {
+		err = -ENOMEM;
+		goto out_unlock;
 	}

 	err = inet_sctp_diag_fill(sk, assoc, rep, req, sk_user_ns(NETLINK_CB(skb).sk),
 				  NETLINK_CB(skb).portid, commp->nlh->nlmsg_seq, 0,
 				  commp->nlh, commp->net_admin);
 	if (err < 0) {
 		WARN_ON(err == -EMSGSIZE);
 		goto out;
 	}
 	release_sock(sk);

 	return nlmsg_unicast(sock_net(skb->sk)->diag_nlsk, rep, NETLINK_CB(skb).portid);

 out:
-	release_sock(sk);
 	kfree_skb(rep);
+out_unlock:
+	release_sock(sk);
 	return err;
 }



